import { expect, test, uniqueName } from "../../fixtures";

const examples = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

for (const { field, value } of examples) {
  test(`rejects vendor with invalid ${field}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
    // Arrange: a valid vendor payload with only the one field under test made invalid
    const member = await apiAs("member");
    const payload: Record<string, unknown> = {
      name: uniqueName("Vendor Validation"),
      category: "software",
      contact_email: "billing@vendor-validation.test",
    };
    payload[field] = value;

    // Act
    const response = await member.post("/api/vendors", { data: payload });

    // Assert
    expect(response.status()).toBe(422);
    const body = await response.json();
    expect(body.error.code).toBe("validation_error");
    expect(JSON.stringify(body)).toContain(field);
  });
}
